<script setup lang="ts">import {computed,ref} from 'vue';import {useRoute} from 'vue-router';import AppShell from '@/components/zs/AppShell.vue';import PageHeader from '@/components/zs/PageHeader.vue';import Panel from '@/components/zs/Panel.vue';import Tabs from '@/components/zs/Tabs.vue';import ActivityTimeline from '@/components/crm/ActivityTimeline.vue';import UserAvatar from '@/components/crm/UserAvatar.vue';import StatusBadge from '@/components/zs/StatusBadge.vue';import ZButton from '@/components/zs/ZButton.vue';import {useCrmData} from '@/composables/useCrmData';import {setPageMeta} from '@/lib/page-meta';setPageMeta('Contact Profile','Contact details and engagement history.');const route=useRoute(),d=useCrmData(),tab=ref('Overview');const item=computed(()=>(d.contacts.data.value??[]).find(x=>x.id===route.params.id)),acts=computed(()=>(d.activities.data.value??[]).filter(x=>x.accountId===item.value?.accountId)),leadIds=computed(()=>new Set((d.leads.data.value??[]).filter(x=>x.accountId===item.value?.accountId).map(x=>x.id))),emails=computed(()=>(d.emails.data.value??[]).filter(x=>leadIds.value.has(x.leadId)));</script>
<template><AppShell><template v-if="item"><PageHeader :title="item.name" :description="`${item.title} at ${item.company}`"><template #actions><StatusBadge :status="item.status"/><ZButton variant="outline">Edit contact</ZButton><ZButton>Log activity</ZButton></template></PageHeader><Panel><Tabs v-model="tab" :items="['Overview','Activity','Notes','Emails','Calls','Tasks','Attachments']"/><div v-if="tab==='Overview'" class="grid gap-6 p-5 lg:grid-cols-[auto_1fr]"><UserAvatar :name="item.name"/><dl class="grid gap-4 text-xs sm:grid-cols-2"><div v-for="[k,v] in Object.entries({Company:item.company,'Job title':item.title,Email:item.email,Phone:item.phone,LinkedIn:item.linkedin,Owner:item.owner,'Last activity':item.lastActivity})" :key="k"><dt class="label-caps">{{k}}</dt><dd class="mt-1 text-content">{{v}}</dd></div></dl></div><div v-else-if="tab==='Activity'" class="p-4"><ActivityTimeline :items="acts"/></div><div v-else-if="tab==='Emails'" class="divide-y divide-line"><article v-for="email in emails" :key="email.id" class="p-4"><div class="flex items-center justify-between gap-3"><p class="text-sm font-medium text-content">{{email.subject}}</p><StatusBadge :status="email.status"/></div><p class="mt-1 text-2xs text-content-muted">{{email.sender}} · {{email.date}} · {{email.sequence}}</p><p class="mt-3 whitespace-pre-wrap text-xs leading-5 text-content-secondary">{{email.body}}</p></article><p v-if="!emails.length" class="p-10 text-center text-sm text-content-muted">No emails recorded yet.</p></div><div v-else class="p-10 text-center text-sm text-content-muted">No {{tab.toLowerCase()}} recorded yet.</div></Panel></template></AppShell></template>
